405→            StepState {
406→                status: StepStatus::Success,
407→                ..Default::default()
408→            },
409→        );
410→
411→        // Save state
412→        state.save(&project).unwrap();
413→
414→        // Verify no temp file remains (it should have been renamed)
415→        let temp_path = StateStore::state_file(&project).with_extension("yml.tmp");
416→        assert!(
