  1→//! Project index management.
  2→//!
  3→//! This module provides the [`ProjectIndex`] for tracking all known
  4→//! projects that Bivvy has been used with.
  5→
  6→use chrono::{DateTime, Utc};
  7→use serde::{Deserialize, Serialize};
  8→use std::collections::HashMap;
  9→use std::fs;
 10→use std::path::PathBuf;
 11→
 12→use super::ProjectId;
 13→
 14→/// Index of all known projects.
 15→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 16→pub struct ProjectIndex {
 17→    pub projects: HashMap<String, ProjectEntry>,
 18→}
 19→
 20→/// Entry for a project in the index.
 21→#[derive(Debug, Clone, Serialize, Deserialize)]
 22→pub struct ProjectEntry {
 23→    pub path: String,
 24→    pub git_remote: Option<String>,
 25→    pub name: String,
 26→    pub last_accessed: DateTime<Utc>,
 27→}
 28→
 29→impl ProjectIndex {
 30→    /// Get the index file path.
 31→    pub fn file_path() -> PathBuf {
 32→        dirs::home_dir()
 33→            .unwrap_or_else(|| PathBuf::from("~"))
 34→            .join(".bivvy")
 35→            .join("projects")
 36→            .join("index.yml")
 37→    }
 38→
 39→    /// Load the project index.
 40→    pub fn load() -> crate::error::Result<Self> {
 41→        let path = Self::file_path();
 42→
 43→        if !path.exists() {
 44→            return Ok(Self::default());
 45→        }
 46→
 47→        let content = fs::read_to_string(&path)?;
 48→        let index: Self = serde_yaml::from_str(&content).map_err(|e| {
 49→            crate::error::BivvyError::ConfigParseError {
 50→                path,
 51→                message: e.to_string(),
 52→            }
 53→        })?;
 54→
 55→        Ok(index)
 56→    }
 57→
 58→    /// Save the project index using atomic write.
 59→    ///
 60→    /// Uses the write-to-temp-then-rename pattern to prevent corruption.
 61→    pub fn save(&self) -> crate::error::Result<()> {
 62→        let path = Self::file_path();
 63→
 64→        if let Some(parent) = path.parent() {
 65→            fs::create_dir_all(parent)?;
 66→        }
 67→
 68→        let content = serde_yaml::to_string(self).map_err(|e| {
 69→            crate::error::BivvyError::ConfigValidationError {
 70→                message: format!("Failed to serialize index: {}", e),
 71→            }
 72→        })?;
 73→
 74→        // Atomic write: write to temp file, then rename
 75→        let temp_path = path.with_extension("yml.tmp");
 76→        fs::write(&temp_path, &content)?;
 77→        fs::rename(&temp_path, &path)?;
 78→
 79→        Ok(())
 80→    }
 81→
 82→    /// Update or add a project to the index.
 83→    pub fn update(&mut self, project_id: &ProjectId) {
 84→        let entry = ProjectEntry {
 85→            path: project_id.path().to_string_lossy().to_string(),
 86→            git_remote: project_id.git_remote().map(String::from),
 87→            name: project_id.name().to_string(),
 88→            last_accessed: Utc::now(),
 89→        };
 90→        self.projects.insert(project_id.hash().to_string(), entry);
 91→    }
 92→
 93→    /// Remove projects that no longer exist on disk.
 94→    pub fn prune(&mut self) -> Vec<String> {
 95→        let mut removed = Vec::new();
 96→
 97→        self.projects.retain(|hash, entry| {
 98→            let exists = std::path::Path::new(&entry.path).exists();
 99→            if !exists {
100→                removed.push(hash.clone());
101→            }
102→            exists
103→        });
104→
105→        removed
106→    }
107→
108→    /// List all projects.
109→    pub fn list(&self) -> impl Iterator<Item = (&str, &ProjectEntry)> {
110→        self.projects.iter().map(|(k, v)| (k.as_str(), v))
111→    }
112→
113→    /// Get a project by hash.
114→    pub fn get(&self, hash: &str) -> Option<&ProjectEntry> {
115→        self.projects.get(hash)
116→    }
117→
118→    /// Number of tracked projects.
119→    pub fn len(&self) -> usize {
120→        self.projects.len()
121→    }
122→
123→    /// Check if index is empty.
124→    pub fn is_empty(&self) -> bool {
125→        self.projects.is_empty()
126→    }
127→}
