  1→//! User preferences persistence.
  2→//!
  3→//! This module provides the [`Preferences`] struct for storing
  4→//! saved user choices like prompt answers and skip behaviors.
  5→
  6→use serde::{Deserialize, Serialize};
  7→use std::collections::HashMap;
  8→use std::fs;
  9→use std::path::PathBuf;
 10→
 11→use super::{ProjectId, StateStore};
 12→
 13→/// Saved user preferences for a project.
 14→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 15→pub struct Preferences {
 16→    /// Saved prompt answers.
 17→    #[serde(default)]
 18→    pub prompts: HashMap<String, String>,
 19→
 20→    /// Skip behavior preferences.
 21→    #[serde(default)]
 22→    pub skip_behavior: HashMap<String, String>,
 23→
 24→    /// Template source preferences (for collision resolution).
 25→    #[serde(default)]
 26→    pub template_sources: HashMap<String, String>,
 27→
 28→    /// Other arbitrary preferences.
 29→    #[serde(default)]
 30→    pub other: HashMap<String, String>,
 31→}
 32→
 33→impl Preferences {
 34→    /// Get the preferences file path.
 35→    pub fn file_path(project_id: &ProjectId) -> PathBuf {
 36→        StateStore::state_dir(project_id).join("preferences.yml")
 37→    }
 38→
 39→    /// Load preferences from disk.
 40→    pub fn load(project_id: &ProjectId) -> crate::error::Result<Self> {
 41→        let path = Self::file_path(project_id);
 42→
 43→        if !path.exists() {
 44→            return Ok(Self::default());
 45→        }
 46→
 47→        let content = fs::read_to_string(&path)?;
 48→        let prefs: Self = serde_yaml::from_str(&content).map_err(|e| {
 49→            crate::error::BivvyError::ConfigParseError {
 50→                path,
 51→                message: e.to_string(),
 52→            }
 53→        })?;
 54→
 55→        Ok(prefs)
 56→    }
 57→
 58→    /// Save preferences to disk using atomic write.
 59→    ///
 60→    /// Uses the write-to-temp-then-rename pattern to prevent corruption.
 61→    pub fn save(&self, project_id: &ProjectId) -> crate::error::Result<()> {
 62→        let dir = StateStore::state_dir(project_id);
 63→        fs::create_dir_all(&dir)?;
 64→
 65→        let path = Self::file_path(project_id);
 66→        let content = serde_yaml::to_string(self).map_err(|e| {
 67→            crate::error::BivvyError::ConfigValidationError {
 68→                message: format!("Failed to serialize preferences: {}", e),
 69→            }
 70→        })?;
 71→
 72→        // Atomic write: write to temp file, then rename
 73→        let temp_path = path.with_extension("yml.tmp");
 74→        fs::write(&temp_path, &content)?;
 75→        fs::rename(&temp_path, &path)?;
 76→
 77→        Ok(())
 78→    }
 79→
 80→    /// Get a saved prompt value.
 81→    pub fn get_prompt(&self, key: &str) -> Option<&str> {
 82→        self.prompts.get(key).map(|s| s.as_str())
 83→    }
 84→
 85→    /// Save a prompt value.
 86→    pub fn set_prompt(&mut self, key: &str, value: &str) {
 87→        self.prompts.insert(key.to_string(), value.to_string());
 88→    }
 89→
 90→    /// Get skip behavior for a step.
 91→    pub fn get_skip_behavior(&self, step: &str) -> Option<&str> {
 92→        self.skip_behavior.get(step).map(|s| s.as_str())
 93→    }
 94→
 95→    /// Save skip behavior for a step.
 96→    pub fn set_skip_behavior(&mut self, step: &str, behavior: &str) {
 97→        self.skip_behavior
 98→            .insert(step.to_string(), behavior.to_string());
 99→    }
100→
101→    /// Get template source for a template.
102→    pub fn get_template_source(&self, template: &str) -> Option<&str> {
103→        self.template_sources.get(template).map(|s| s.as_str())
104→    }
105→
106→    /// Save template source preference.
107→    pub fn set_template_source(&mut self, template: &str, source: &str) {
108→        self.template_sources
109→            .insert(template.to_string(), source.to_string());
110→    }
111→}
