//! Centralized directory management for Bivvy.
//!
//! This module provides [`BivvyDirs`], the single source of truth
//! for all Bivvy system paths. It respects platform-standard directories
//! (XDG on Linux, `~/Library/` on macOS, `%APPDATA%` on Windows) and
//! supports a `BIVVY_HOME` environment variable override for backward
//! compatibility.

use std::path::{Path, PathBuf};

pub struct BivvyDirs {
    config_dir: PathBuf,
    data_dir: PathBuf,
    cache_dir: PathBuf,
}

impl BivvyDirs {
    pub fn new(config_dir: PathBuf, data_dir: PathBuf, cache_dir: PathBuf) -> Self {
        Self { config_dir, data_dir, cache_dir }
    }

    pub fn from_env() -> Self {
        if let Ok(home) = std::env::var("BIVVY_HOME") {
            let home = PathBuf::from(home);
            return Self::new(home.clone(), home.clone(), home);
        }

        let config = dirs::config_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("bivvy");
        let data = dirs::data_local_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("bivvy");
        let cache = dirs::cache_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("bivvy");

        Self::new(config, data, cache)
    }

    // Config paths
    pub fn user_config_file(&self) -> PathBuf {
        self.config_dir.join("config.yml")
    }

    pub fn user_templates_dir(&self) -> PathBuf {
        self.config_dir.join("templates")
    }

    // Data paths
    pub fn project_state_dir(&self, project_hash: &str) -> PathBuf {
        self.data_dir.join("projects").join(project_hash)
    }

    pub fn project_index_file(&self) -> PathBuf {
        self.data_dir.join("projects").join("index.yml")
    }

    pub fn failure_reports_dir(&self) -> PathBuf {
        self.data_dir.join("failure-reports")
    }

    pub fn sessions_dir(&self) -> PathBuf {
        self.data_dir.join("sessions")
    }

    pub fn feedback_file(&self) -> PathBuf {
        self.data_dir.join("feedback.jsonl")
    }

    // Cache paths
    pub fn template_cache_dir(&self) -> PathBuf {
        self.cache_dir.join("templates")
    }
}

impl Default for BivvyDirs {
    fn default() -> Self {
        Self::from_env()
    }
}
```

